const rows = $input.all().map(i => i.json);
const bySymbol = {};
for (const r of rows) {
  if (!bySymbol[r.symbol]) bySymbol[r.symbol] = [];
  bySymbol[r.symbol].push(r);
}
const summaries = [];
const lastPrices = {};
for (const symbol in bySymbol) {
  const arr = bySymbol[symbol].sort((a,b) => new Date(a.open_time) - new Date(b.open_time));
  const first = parseFloat(arr[0].close);
  const last = parseFloat(arr[arr.length-1].close);
  const changePct = (((last - first) / first) * 100).toFixed(2);
  summaries.push(`${symbol}: gia dau ${first}, gia hien tai ${last}, thay doi ${changePct}%`);
  lastPrices[symbol] = last;
}
const symbolList = Object.keys(bySymbol);
const prompt = `Ban la AI phan tich thi truong crypto ngan han. Du lieu 2 gio gan nhat:\n${summaries.join('\n')}\n\nTra loi DUY NHAT mot JSON array, khong them chu nao khac, dung format:\n[{"symbol": "BTCUSDT", "signal": "BUY|SELL|HOLD", "reason": "giai thich ngan gon 1 cau"}]\n\nPhai co du 1 object cho moi symbol: ${symbolList.join(', ')}`;
return [{ json: { prompt, last_prices: lastPrices, symbol_list: symbolList } }];

const raw = $input.first().json;
const lastPrices = $('Build Prompt').first().json.last_prices;
const symbolList = $('Build Prompt').first().json.symbol_list;
let parsed;
try {
  parsed = JSON.parse(raw.response);
} catch (e) {
  parsed = [];
}
if (!Array.isArray(parsed) || parsed.length === 0) {
  parsed = symbolList.map(symbol => ({ symbol, signal: "HOLD", reason: "parse_error: AI khong tra ve JSON hop le" }));
}
return parsed.map(p => ({
  json: {
    symbol: p.symbol,
    signal: (p.signal || "HOLD").toUpperCase(),
    reason: p.reason || "",
    price_at_signal: lastPrices[p.symbol] || null
  }
}));

const items = $input.all();
const hasError = items.some(i => i.json && i.json.error);
const meta = $('Set Workflow Meta').first().json;
return [{
  json: {
    workflow_id: meta.workflow_id,
    version: meta.version,
    status: hasError ? "partial_error" : "success",
    timestamp: new Date().toISOString(),
    data: items.map(i => i.json)
  }
}];
